	s.idx++
	return tok
}

func (s *Scanner) NextInt() int {
	val, _ := strconv.Atoi(s.Next())
	return val
}

func (s *Scanner) NextLong() int64 {
	val, _ := strconv.ParseInt(s.Next(), 10, 64)
	return val
}

type Matrix struct {
	n int
	a [][]int64
