	a := make([][]int64, n)
	for i := range a {
		a[i] = make([]int64, n)
	}
	return &Matrix{n: n, a: a}
}

func Identity(n int) *Matrix {
	m := NewMatrix(n)
	for i := 0; i < n; i++ {
		m.a[i][i] = 1
	}
	return m
}

func (m *Matrix) Multiply(other *Matrix) *Matrix {
	res := NewMatrix(m.n)
	for i := 0; i < m.n; i++ {
		for k := 0; k < m.n; k++ {
			if m.a[i][k] == 0 {
				continue
			}
			aik := m.a[i][k]
			for j := 0; j < m.n; j++ {
				res.a[i][j] = (res.a[i][j] + aik*other.a[k][j]) % MOD
			}
		}
	}
	return res
}

func (m *Matrix) ModPow(exp int64) *Matrix {
	result := Identity(m.n)
	base := m
	for exp > 0 {
		if exp&1 == 1 {
			result = result.Multiply(base)
		}
		base = base.Multiply(base)
